/** The category of each id, for a lookup while rendering. */
export const DOS_GAME_CATEGORY_BY_ID: Record<string, DosGameCategory> =
  Object.fromEntries(DOS_GAME_CATEGORIES.map((category) => [category.id, category]));

/**
 * The label of a category, or the id itself when the category is
 * one this build does not know — a game is never left nameless.
 */
export function categoryLabel(id: string): string {
  return DOS_GAME_CATEGORY_BY_ID[id]?.label ?? id;
}
